def ip_to_int(ip):
    parts = ip.split(".")
    if len(parts) != 4:
        raise ValueError(f"bad ip: {ip}")
    n = 0
    for p in parts:
        octet = int(p)
        if octet < 0 or octet > 255:
            raise ValueError(f"bad octet in {ip}")
        n = (n << 8) | octet
    return n


def cidr_contains(cidr, ip):
    """True iff `ip` falls inside the `cidr` block (e.g. '10.0.0.0/8')."""
    network, bits = cidr.split("/")
    prefix = int(bits)
    if prefix < 0 or prefix > 32:
        raise ValueError(f"bad prefix: {cidr}")
    mask = (0xFFFFFFFF << (32 - prefix)) & 0xFFFFFFFF if prefix else 0
    return (ip_to_int(ip) & mask) == (ip_to_int(network) & mask)

