from netblock import cidr_contains


def test_returns_bool():
    assert isinstance(cidr_contains("10.0.0.0/8", "10.0.0.1"), bool)


def test_same_address():
    assert cidr_contains("10.0.0.1/32", "10.0.0.1") is True


def test_obvious_inside():
    assert cidr_contains("10.0.0.0/8", "10.0.0.1") is True


def test_obvious_outside():
    assert cidr_contains("10.0.0.0/8", "192.168.0.1") is False
